// api/auth.js
const API_URL = "/api/auth";

export const getAccessToken = () => {
    return localStorage.getItem("accessToken");
};

export const login = async (email, password) => {
    const res = await fetch(`${API_URL}/login`, {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
            "Accept": "application/json"
        },
        body: JSON.stringify({ email, password }),
    });

    if (!res.ok) {
        const text = await res.text();
        throw new Error(text || "Login failed");
    }

    const data = await res.json();
    const tokenPayload = JSON.parse(atob(data.accessToken.split('.')[1]));
    const roles = tokenPayload.roles || [];

    return {
        ...data,
        roles: roles
    };
};

export async function register(email, password) {
    const res = await fetch(`${API_URL}/register`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
    });

    if (!res.ok) {
        let error = new Error("Ошибка регистрации");
        error.status = res.status;
        throw error;
    }

    return res.json().catch(() => ({}));
}

export const logout = () => {
    localStorage.removeItem("accessToken");
    localStorage.removeItem("refreshToken");
    localStorage.removeItem("userEmail");
    localStorage.removeItem("userRoles");
};

export const saveTokens = (access, refresh, email, roles) => {
    localStorage.setItem("accessToken", access);
    localStorage.setItem("refreshToken", refresh);
    localStorage.setItem("userEmail", email);
    localStorage.setItem("userRoles", JSON.stringify(roles));
};

export const getCurrentUser = () => {
    const token = getAccessToken();
    let roles = [];

    if (token) {
        const decoded = decodeJWT(token);
        if (decoded) {
            roles = decoded.roles || [];
        }
    }

    return {
        email: localStorage.getItem("userEmail"),
        roles: roles
    };
};
export const decodeJWT = (token) => {
    try {
        const payload = token.split('.')[1];
        return JSON.parse(atob(payload));
    } catch (error) {
        console.error("Error decoding JWT:", error);
        return null;
    }
};



// Новые функции для управления ролями
export const assignRole = async (email, role) => {
    const token = getAccessToken();
    const res = await fetch(`${API_URL}/assign-role`, {
        method: "POST",
        headers: {
            "Authorization": `Bearer ${token}`,
            "Content-Type": "application/json"
        },
        body: JSON.stringify({ email, role })
    });

    if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.message || `Ошибка: ${res.status}`);
    }

    return res.json();
};

export const getUsers = async () => {
    const token = getAccessToken();
    // Этот эндпоинт нужно будет реализовать на бэкенде
    const res = await fetch(`${API_URL}/users`, {
        method: "GET",
        headers: {
            "Authorization": `Bearer ${token}`
        }
    });

    if (!res.ok) {
        throw new Error("Ошибка получения пользователей");
    }

    return res.json();
};
